<script setup>
import { computed, onMounted, ref } from 'vue'
import { CalendarDays, Check, Clock3, Loader2, MapPin, Search, Send, Users, X } from 'lucide-vue-next'
import DashboardLayout from '../components/layouts/DashboardLayout.vue'
import { useAuthStore } from '../stores/auth'
import { useCampagnesStore } from '../stores/campagnes'
import { useModalStore } from '../stores/modal'
import { usePlanningsStore } from '../stores/plannings' const authStore = useAuthStore()
const campagnesStore = useCampagnesStore()
const modalStore = useModalStore()
const planningsStore = usePlanningsStore() const selectedFormation = ref('')
const selectedCohorte = ref('')
const selectedDay = ref('')
const selectedPlanningId = ref('')
const convocation = ref(null)
const searchTerm = ref('')
const drafts = ref({})
const bulkCount = ref(10)
const loadingCandidates = ref(false)
const sending = ref(false) const canManage = computed(() => authStore.user?.role === 'Administrateur' || authStore.user?.role === 'Équipe Gestion de Projet') const upcomingPlannings = computed(() => { const today = new Date().toISOString().slice(0, 10) return planningsStore.plannings.filter(p => p.date >= today)
})
const formations = computed(() => { const values = new Map() upcomingPlannings.value.forEach(p => values.set(p.formation_nom, p.formation_nom)) return [...values.values()].filter(Boolean)
})
const cohortes = computed(() => { const values = new Map() upcomingPlannings.value .filter(p => !selectedFormation.value || p.formation_nom === selectedFormation.value) .forEach(p => values.set(p.cohorte_nom, p.cohorte_nom)) return [...values.values()].filter(Boolean)
})
const filteredPlannings = computed(() => upcomingPlannings.value.filter(p => (!selectedFormation.value || p.formation_nom === selectedFormation.value) && (!selectedCohorte.value || p.cohorte_nom === selectedCohorte.value)))
const days = computed(() => [...new Set(filteredPlannings.value.map(p => p.date))])
const daySlots = computed(() => filteredPlannings.value .filter(p => p.date === selectedDay.value) .sort((a, b) => a.heureDebut.localeCompare(b.heureDebut)))
const activeDraftIds = computed(() => drafts.value[selectedPlanningId.value] || [])
const selectedPlanning = computed(() => daySlots.value.find(p => p.id === selectedPlanningId.value) || null)
const filteredCandidates = computed(() => { if (!convocation.value) return [] const query = searchTerm.value.trim().toLocaleLowerCase('fr') return convocation.value.candidats.filter(c => !query || [c.nom, c.numero, c.email].some(v => v?.toLocaleLowerCase('fr').includes(query)))
})
const eligibleCandidates = computed(() => filteredCandidates.value.filter(c => c.eligible && !isDraftedElsewhere(c.id)))
const availableCandidates = computed(() => eligibleCandidates.value.filter(c => !activeDraftIds.value.includes(c.id)))
const allEligibleSelected = computed(() => eligibleCandidates.value.length > 0 && eligibleCandidates.value.every(c => activeDraftIds.value.includes(c.id)))
const plannedCount = computed(() => Object.values(drafts.value).flat().length)
const totalCandidates = computed(() => convocation.value?.candidats.filter(c => c.eligible).length || 0)
const activeRemaining = computed(() => Math.max((convocation.value?.places_restantes || 0) - activeDraftIds.value.length, 0))
const hasDraft = computed(() => plannedCount.value > 0) const formatDay = d => new Intl.DateTimeFormat('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(`${d}T12:00:00`))
const formatTime = t => t?.slice(0, 5)
const isDraftedElsewhere = id => Object.entries(drafts.value).some(([pid, ids]) => pid !== selectedPlanningId.value && ids.includes(id))
const slotDraftCount = id => (drafts.value[id] || []).length const chooseDefaultSlot = async () => { if (!days.value.length) { selectedDay.value = ''; selectedPlanningId.value = ''; convocation.value = null; return } if (!days.value.includes(selectedDay.value)) selectedDay.value = days.value[0] if (!daySlots.value.some(s => s.id === selectedPlanningId.value)) selectedPlanningId.value = daySlots.value[0]?.id || '' await loadCandidates()
}
const loadCandidates = async () => { if (!selectedPlanningId.value) { convocation.value = null; return } loadingCandidates.value = true convocation.value = await planningsStore.fetchConvocationCandidats(selectedPlanningId.value) loadingCandidates.value = false
}
const selectFormation = () => { selectedCohorte.value = ''; chooseDefaultSlot() }
const selectCohorte = () => chooseDefaultSlot()
const selectDay = date => { selectedDay.value = date; selectedPlanningId.value = daySlots.value[0]?.id || ''; loadCandidates() }
const selectSlot = id => { selectedPlanningId.value = id; searchTerm.value = ''; loadCandidates() }
const canSelect = c => c.eligible && !isDraftedElsewhere(c.id) && (activeDraftIds.value.includes(c.id) || activeRemaining.value > 0)
const toggleCandidate = id => { const current = activeDraftIds.value const exists = current.includes(id) if (!exists && !activeRemaining.value) return drafts.value = { ...drafts.value, [selectedPlanningId.value]: exists ? current.filter(cid => cid !== id) : [...current, id] }
}
const toggleAllEligible = () => { if (allEligibleSelected.value) { drafts.value = { ...drafts.value, [selectedPlanningId.value]: [] }; return } const ids = eligibleCandidates.value.slice(0, activeRemaining.value).map(c => c.id) drafts.value = { ...drafts.value, [selectedPlanningId.value]: [...activeDraftIds.value, ...ids] }
}
const addFirstCandidates = () => { const requested = Number(bulkCount.value) if (!Number.isInteger(requested) || requested < 1 || !activeRemaining.value) return const needed = Math.max(requested - activeDraftIds.value.length, 0) const ids = availableCandidates.value.slice(0, Math.min(needed, activeRemaining.value)).map(c => c.id) if (!ids.length) return drafts.value = { ...drafts.value, [selectedPlanningId.value]: [...activeDraftIds.value, ...ids] }
}
const clearDrafts = async () => { if (!hasDraft.value) return const confirmed = await modalStore.showConfirm('Les sélections en brouillon seront supprimées.', 'Réinitialiser le brouillon', { confirmText: 'Réinitialiser', variant: 'danger' }) if (confirmed) drafts.value = {}
}
const saveDraft = () => modalStore.showAlert('Votre brouillon est conservé tant que vous restez sur cette session.', 'Brouillon enregistré', 'success')
const sendConvocations = async () => { if (!hasDraft.value || sending.value) return const confirmed = await modalStore.showConfirm( `${plannedCount.value} candidat(s) seront affectés aux créneaux sélectionnés.`, 'Envoyer les convocations', { confirmText: 'Envoyer les convocations', variant: 'primary' }) if (!confirmed) return sending.value = true let sent = 0 for (const [planningId, candidateIds] of Object.entries(drafts.value)) { if (!candidateIds.length) continue const result = await planningsStore.assignerCandidats(planningId, candidateIds) if (!result) { sending.value = false; return } sent += result.affectes const next = { ...drafts.value }; delete next[planningId]; drafts.value = next } drafts.value = {} await planningsStore.fetchPlannings() await chooseDefaultSlot() sending.value = false await modalStore.showAlert(`${sent} convocation(s) créées avec succès.`, 'Convocations envoyées', 'success')
} onMounted(async () => { await Promise.all([planningsStore.fetchPlannings(), campagnesStore.fetchFormations(), campagnesStore.fetchCohortes()]) await chooseDefaultSlot()
})
</script> <template> <DashboardLayout> <template #header> <div class="flex items-center gap-3"> <div class="w-7 h-7 rounded-lg bg-[#E30046] flex items-center justify-center flex-shrink-0"> <Send class="w-3.5 h-3.5 text-white" /> </div> <div> <h2 class="text-lg font-extrabold text-[#01313E] leading-tight">Convocations</h2> </div> </div> </template> <!-- Error banner --> <div v-if="planningsStore.error" class="mb-5 flex items-center gap-3 rounded-2xl border border-[#E30046]/30 bg-[#E30046]/[.04] px-5 py-3.5 text-sm text-[#E30046] font-medium animate-fade-in"> {{ planningsStore.error }} </div> <!-- ── TOP TOOLBAR ──────────────────────────────── --> <section class="animate-fade-in mb-6 grid items-end gap-4 rounded-3xl border border-[#01313E]/10 bg-white p-5 sm:grid-cols-2 lg:grid-cols-[1fr_1fr_auto_auto]"> <div> <label class="form-label">Formation</label> <select v-model="selectedFormation" @change="selectFormation" class="input-field text-sm"> <option value="">Toutes les formations</option> <option v-for="f in formations" :key="f" :value="f">{{ f }}</option> </select> </div> <div> <label class="form-label">Promotion</label> <select v-model="selectedCohorte" :disabled="!cohortes.length" @change="selectCohorte" class="input-field text-sm"> <option value="">Toutes les promotions</option> <option v-for="c in cohortes" :key="c" :value="c">{{ c }}</option> </select> </div> <div class="flex items-center gap-3 border-l border-[#01313E]/10 pl-5"> <div class="w-9 h-9 rounded-xl bg-[#01313E]/6 flex items-center justify-center flex-shrink-0"> <Users class="w-4 h-4 text-[#01313E]" /> </div> <div> <p class="text-xl font-black text-[#01313E] leading-none">{{ totalCandidates }}</p> <p class="text-[11px] text-[#01313E]/50 font-medium mt-0.5">candidats</p> </div> </div> <p class="hidden text-xs text-[#01313E]/40 text-right lg:block self-center"> Sélectionnez un créneau<br>pour préparer ses convocations. </p> </section> <!-- ── LOADING ──────────────────────────────────── --> <div v-if="planningsStore.loading && !upcomingPlannings.length" class="flex h-52 items-center justify-center"> <Loader2 class="h-8 w-8 animate-spin text-[#E30046]" /> </div> <!-- ── EMPTY STATE ──────────────────────────────── --> <div v-else-if="!upcomingPlannings.length" class="empty-state border border-dashed border-[#01313E]/15 rounded-3xl animate-fade-in"> <div class="empty-state-icon"> <CalendarDays class="w-8 h-8" /> </div> <h3 class="text-lg font-bold text-[#01313E] mb-2">Aucun créneau à venir</h3> <p class="text-[#01313E]/50 text-sm">Créez un planning avant de préparer des convocations.</p> </div> <template v-else> <!-- ── DAY PICKER ─────────────────────────────── --> <div class="mb-5 animate-fade-in stagger-1"> <label class="form-label">Date de convocation</label> <select id="convocation-day" v-model="selectedDay" @change="selectDay(selectedDay)" class="input-field max-w-sm font-semibold capitalize"> <option v-for="(day, i) in days" :key="day" :value="day"> Jour {{ i + 1 }} — {{ formatDay(day) }} </option> </select> </div> <!-- ── TWO-COLUMN WORKSPACE ───────────────────── --> <div class="grid gap-5 lg:grid-cols-[minmax(280px,.9fr)_minmax(380px,1.1fr)] animate-fade-in stagger-2"> <!-- LEFT — Schedule --> <section class="card overflow-hidden flex flex-col"> <div class="flex items-start justify-between border-b border-[#01313E]/8 px-5 py-4"> <div> <h3 class="text-sm font-extrabold text-[#01313E]">Structure de la journée</h3> <p class="mt-0.5 text-xs text-[#01313E]/50 capitalize"> {{ selectedDay ? formatDay(selectedDay) : 'Choisissez une journée' }} </p> </div> <span class="badge badge-dark">{{ daySlots.length }} créneau(x)</span> </div> <div class="flex-1 space-y-2.5 p-4 overflow-y-auto"> <button v-for="slot in daySlots" :key="slot.id" type="button" @click="selectSlot(slot.id)" class="w-full rounded-2xl border p-4 text-left transition-all duration-150" :class="selectedPlanningId === slot.id ? 'border-[#E30046] bg-[#E30046]/[.04]' : 'border-[#01313E]/10 hover:border-[#01313E]/30 hover:bg-[#01313E]/[.02]'" > <div class="flex items-center justify-between mb-2"> <div class="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest" :class="selectedPlanningId === slot.id ? 'text-[#E30046]' : 'text-[#01313E]/40'"> <Clock3 class="h-3 w-3" /> Créneau </div> <span class="text-[11px] text-[#01313E]/50">Cap. {{ slot.capacite }}</span> </div> <p class="text-base font-extrabold" :class="selectedPlanningId === slot.id ? 'text-[#E30046]' : 'text-[#01313E]'"> {{ formatTime(slot.heureDebut) }} – {{ formatTime(slot.heureFin) }} </p> <div class="flex items-center gap-1 mt-1.5 text-xs text-[#01313E]/50"> <MapPin class="h-3 w-3 flex-shrink-0" /> {{ slot.lieu || slot.localisation || 'Lieu à préciser' }} </div> <div v-if="slotDraftCount(slot.id)" class="mt-2.5 inline-flex items-center gap-1.5 rounded-full bg-[#01313E] px-2.5 py-1 text-[10px] font-bold text-white"> <Check class="h-3 w-3" /> {{ slotDraftCount(slot.id) }} en brouillon </div> </button> </div> </section> <!-- RIGHT — Candidates --> <section class="card overflow-hidden flex flex-col"> <div class="flex items-start justify-between border-b border-[#01313E]/8 px-5 py-4"> <div> <h3 class="text-sm font-extrabold text-[#01313E]">Candidats non assignés</h3> <p class="mt-0.5 text-xs text-[#01313E]/50"> {{ selectedPlanning ? `${formatTime(selectedPlanning.heureDebut)} – ${formatTime(selectedPlanning.heureFin)}` : 'Sélectionnez un créneau' }} </p> </div> <span v-if="convocation" class="badge badge-outline-dark"> {{ activeRemaining }} place(s) </span> </div> <!-- Search & bulk tools --> <div class="flex flex-wrap gap-2 border-b border-[#01313E]/8 p-3"> <label class="relative flex-1 min-w-48"> <Search class="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[#01313E]/35 pointer-events-none" /> <input v-model="searchTerm" class="input-field pl-9 text-xs h-9" placeholder="Rechercher un candidat…" /> </label> <div v-if="canManage" class="flex overflow-hidden rounded-xl border border-[#01313E]/12"> <label for="bulk-count" class="sr-only">Nombre de candidats</label> <input id="bulk-count" v-model.number="bulkCount" type="number" min="1" :max="convocation?.capacite || 1" class="w-12 border-0 bg-white px-2 text-center text-xs font-bold text-[#01313E] outline-none focus:bg-[#01313E]/5" /> <button type="button" :disabled="!availableCandidates.length || !activeRemaining" @click="addFirstCandidates" class="bg-[#01313E] px-3 py-2 text-xs font-bold text-white transition hover:bg-[#01222B] disabled:cursor-not-allowed disabled:opacity-50"> Sélectionner {{ bulkCount || 0 }} </button> </div> <button v-if="canManage && eligibleCandidates.length" class="rounded-xl px-3 text-xs font-bold text-[#01313E] border border-[#01313E]/15 hover:bg-[#01313E]/5 transition" type="button" @click="toggleAllEligible"> {{ allEligibleSelected ? 'Tout retirer' : 'Tout sélectionner' }} </button> </div> <!-- Candidate list --> <div v-if="loadingCandidates" class="flex h-52 items-center justify-center"> <Loader2 class="h-6 w-6 animate-spin text-[#E30046]" /> </div> <div v-else class="flex-1 max-h-[400px] overflow-y-auto divide-y divide-[#01313E]/6"> <button v-for="c in filteredCandidates" :key="c.id" type="button" class="w-full flex items-center gap-3 px-4 py-3 text-left transition" :class="{ 'bg-[#01313E]/[.03]': activeDraftIds.includes(c.id), 'opacity-45 pointer-events-none': !canSelect(c) && !activeDraftIds.includes(c.id), 'hover:bg-[#01313E]/[.02]': canSelect(c) }" :disabled="!canManage || (!canSelect(c) && !activeDraftIds.includes(c.id))" @click="toggleCandidate(c.id)" > <!-- Checkbox --> <span class="flex-shrink-0 w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all" :class="activeDraftIds.includes(c.id) ? 'bg-[#E30046] border-[#E30046] text-white' : 'border-[#01313E]/20'"> <Check v-if="activeDraftIds.includes(c.id)" class="h-3 w-3" /> </span> <!-- Avatar --> <span class="flex-shrink-0 w-8 h-8 rounded-xl bg-[#01313E] text-white text-[10px] font-black flex items-center justify-center"> {{ c.nom?.split(' ').map(p => p[0]).slice(0, 2).join('') || '?' }} </span> <!-- Info --> <span class="flex-1 min-w-0"> <strong class="block text-xs font-bold text-[#01313E] truncate">{{ c.nom || 'Candidat sans nom' }}</strong> <small class="text-[11px] text-[#01313E]/50 truncate block"> {{ c.numero }}<template v-if="c.email"> · {{ c.email }}</template> </small> <em v-if="!c.eligible" class="text-[11px] text-[#E30046] not-italic">{{ c.raison }}</em> <em v-else-if="isDraftedElsewhere(c.id)" class="text-[11px] text-[#01313E]/50 not-italic">Placé dans un autre créneau.</em> </span> <span v-if="activeDraftIds.includes(c.id)" class="flex-shrink-0 rounded-full bg-[#01313E] px-2 py-0.5 text-[10px] font-bold text-white"> Prévu </span> </button> <p v-if="!filteredCandidates.length" class="px-5 py-12 text-center text-sm text-[#01313E]/50"> Aucun candidat ne correspond à votre recherche. </p> </div> </section> </div> <!-- ── FOOTER BAR ─────────────────────────────── --> <footer v-if="canManage" class="sticky bottom-4 z-10 mt-5 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#01313E]/10 bg-white px-5 py-3.5 animate-fade-in"> <p class="text-xs text-[#01313E]/70 flex items-center gap-2"> <span class="inline-block w-2 h-2 rounded-full flex-shrink-0" :class="hasDraft ? 'bg-[#E30046]' : 'bg-[#01313E]/25'"></span> <span> <b class="text-[#01313E] font-extrabold">{{ plannedCount }}</b> candidat(s) prêt(s) à être convoqué(s) <span v-if="hasDraft" class="text-[#E30046]/80"> · brouillon non envoyé</span> </span> </p> <div class="flex flex-wrap gap-2"> <button class="btn-secondary text-xs px-3 py-2" :disabled="!hasDraft || sending" @click="clearDrafts"> <X class="h-3.5 w-3.5 mr-1" />Réinitialiser </button> <button class="btn-secondary text-xs px-3 py-2" :disabled="!hasDraft || sending" @click="saveDraft"> Sauvegarder </button> <button class="btn-primary text-xs px-4 py-2" :disabled="!hasDraft || sending" @click="sendConvocations"> <Loader2 v-if="sending" class="mr-1.5 h-3.5 w-3.5 animate-spin" /> <Send v-else class="mr-1.5 h-3.5 w-3.5" /> Envoyer les convocations </button> </div> </footer> </template> </DashboardLayout>
</template>
